mapper.select:
select id, session_id, user_id, role, content, risk_level, tokens, created_at
from ai_chat_message
where session_id = #{sessionId}
  and user_id = #{userId}
order by id asc

select count(1)
from ai_chat_message
where session_id = #{sessionId}
  and user_id = #{userId}

mapper.delete:
delete from ai_chat_message
where session_id = #{sessionId}
  and user_id = #{userId}
